      <form id="support-form" novalidate>
        <div class="form-grid">
          <div class="form-field full" id="field-name">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="full-name-error">
            <p class="error-message" id="full-name-error" aria-live="polite"></p>
          </div>

          <div class="form-field full" id="field-email">
            <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
            <input id="email-address" name="emailAddress" type="email" autocomplete="email" required aria-describedby="email-address-error">
            <p class="error-message" id="email-address-error" aria-live="polite"></p>
          </div>

          <div class="form-field full" id="field-phone">
            <label for="phone-number">Phone number</label>
            <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-number-hint phone-number-error">
            <p class="field-hint" id="phone-number-hint">Optional. Use a format like +1 555 123 4567 or 555-123-4567.</p>
            <p class="error-message" id="phone-number-error" aria-live="polite"></p>
          </div>
        </div>

        <div class="actions">
          <button type="submit">Send message</button>
        </div>

        <p class="status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const fields = [
      {
        input: document.getElementById('full-name'),
        field: document.getElementById('field-name'),
        error: document.getElementById('full-name-error'),
        validate: value => {
          const trimmed = value.trim();
          if (!trimmed) return 'Full name is required.';
          if (trimmed.length < 2) return 'Enter a longer full name.';
          return '';
        }
      },
      {
        input: document.getElementById('email-address'),
        field: document.getElementById('field-email'),
        error: document.getElementById('email-address-error'),
        validate: value => {
          const trimmed = value.trim();
          if (!trimmed) return 'Email address is required.';
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) return 'Enter a valid email address.';
          return '';
        }
      },
      {
        input: document.getElementById('phone-number'),
        field: document.getElementById('field-phone'),
        error: document.getElementById('phone-number-error'),
        validate: value => {
          const trimmed = value.trim();
          if (!trimmed) return '';
          if (!/^\+?[0-9 ()-]{7,}$/.test(trimmed) || !/\d/.test(trimmed)) {
            return 'Enter a valid phone number, such as +1 555 123 4567.';
          }
          return '';
        }
      }
    ];

    const status = document.getElementById('form-status');

    function setFieldState({ input, field, error }, message) {
      const invalid = Boolean(message);
      if (invalid) {
        input.setAttribute('aria-invalid', 'true');
      } else {
        input.removeAttribute('aria-invalid');
      }
      error.textContent = message;
      field.classList.toggle('is-invalid', invalid);
    }

    function validateField(config) {
      const message = config.validate(config.input.value);
      setFieldState(config, message);
      return !message;
    }

    fields.forEach(({ input }) => {
      input.addEventListener('input', () => {
        validateField(fields.find(field => field.input === input));
        status.textContent = '';
      });

      input.addEventListener('blur', () => {
        validateField(fields.find(field => field.input === input));
      });
    });

    form.addEventListener('submit', event => {
      event.preventDefault();
      status.textContent = '';

      const firstInvalid = fields.find(field => !validateField(field));
      if (firstInvalid) {
        firstInvalid.input.focus();
        return;
      }

      status.textContent = 'Message ready to send.';
      form.reset();
      fields.forEach(field => setFieldState(field, ''));
    });
